#!/usr/bin/env node

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const web = path.join(root, 'web');
const templatePath = path.join(web, 'index.template.html');
const outputPath = path.join(web, 'index.html');

function read(relativePath) {
  return fs.readFileSync(path.join(root, relativePath), 'utf8');
}

function escapeScript(source) {
  return source
    .replace(/<\/script/gi, '<\\/script')
    .replace(/<!--/g, '<\\!--');
}

function build() {
  let html = fs.readFileSync(templatePath, 'utf8');
  const styles = [read('web/style.css'), read('web/addon.css')].join('\n');
  const schema = JSON.stringify(read('setup_playtime_airdrops.sql'))
    .replace(/</g, '\\u003c')
    .replace(/>/g, '\\u003e')
    .replace(/&/g, '\\u0026');
  const scripts = [
    read('web/dune-addon-bridge.js'),
    read('web/grant_logic.js'),
    `window.__AIRDROP_SCHEMA_SQL = ${schema};`,
    read('web/addon.js')
  ].map(escapeScript).join('\n\n');

  html = html.replace(
    '  <link rel="stylesheet" href="style.css">',
    () => `  <meta name="dune-airdrop-runtime" content="self-contained">\n  <style>\n${styles}\n  </style>`
  );
  html = html.replace(
    /  <!-- Script tags -->\n  <script src="\.\/dune-addon-bridge\.js"><\/script>\n  <script src="grant_logic\.js\?v=1\.3\.0"><\/script>\n  <script src="addon\.js\?v=1\.3\.0"><\/script>/,
    () => `  <!-- Self-contained Console runtime bundle. Generated by scripts/build_web_bundle.js. -->\n  <script>\n${scripts}\n  </script>`
  );
  html = html.replace(/[ \t]+(?=\r?\n)/g, '');

  if (/<(?:script|link)\b[^>]+\bsrc=|<link\b[^>]+\bhref=/i.test(html)) {
    throw new Error('Generated entry still contains an external script or stylesheet reference.');
  }
  if (!html.includes('window.__AIRDROP_SCHEMA_SQL')) {
    throw new Error('Generated entry does not contain the embedded schema SQL.');
  }
  return html;
}

const output = build();
if (process.argv.includes('--check')) {
  if (!fs.existsSync(outputPath) || fs.readFileSync(outputPath, 'utf8') !== output) {
    console.error('web/index.html is not current. Run: node scripts/build_web_bundle.js');
    process.exit(1);
  }
  console.log('Web runtime bundle is current.');
} else {
  fs.writeFileSync(outputPath, output);
  console.log(`Built ${path.relative(root, outputPath)}.`);
}
